/**
 * Framework ids whose AUTO-captured model span runs THROUGH `withSpan`, making
 * it mockable on replay. Every other framework's `auto` spans are observe-only:
 * they are recorded but not wrapped, so replay cannot short-circuit them.
 *
 * Includes agent-facing aliases that are not registry ids in their own right:
 * `vercel` is tagged by the analyzer for the same Vercel AI SDK integration as
 * `vercel-ai-sdk`.
 *
 * The ROOT span is deliberately out of scope: it is never mockable regardless of
 * framework because it starts the replay, a universal rule enforced separately.
 */
export declare const WITHSPAN_MODEL_FRAMEWORKS: ReadonlySet<string>;
/** True when this framework's auto-captured model span is mockable on replay. */
export declare function hasWithSpanModelCall(framework: string | undefined): boolean;
